            if (pricingEl) decisions.pricingStrategy = parseFloat(pricingEl.value);

            var categoryEl = document.getElementById('categoryInput');
            if (categoryEl) decisions.categoryFocus = categoryEl.value;

            var safetyEl = document.getElementById('safetyStockInput');
            if (safetyEl) decisions.safetyStock = safetyEl.value;

            var storeEl = document.getElementById('storeInput');
            if (storeEl) decisions.storeInvestment = parseInt(storeEl.value);

            var onlineEl = document.getElementById('onlineInput');
            if (onlineEl) decisions.onlineInvestment = parseInt(onlineEl.value);

            var vendorEl = document.getElementById('vendorInput');
            if (vendorEl) decisions.vendorStrategy = vendorEl.value;

