            var growthMult = 1.0 + round.marketGrowth;

            var eventImpact = 1.0;
            var eventMarginImpact = 0;
            if (period === 2) {
                if (pricingAdj >= 0) {
                    eventImpact = 0.92;
                } else {
                    eventImpact = 1.02;
                    eventMarginImpact = -0.02;
